-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- can_edit_checklist_templates tests 'editor role in ANY org' and 'member of this org' separately
-- targets: c03
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public.can_edit_checklist_templates(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.organization_members m
             JOIN public.organizations o ON o.id = m.organization_id
            WHERE m.user_id = (SELECT auth.uid())
              AND (m.role IN ('broker', 'admin', 'it_admin')
                   OR o.personal_owner_user_id = m.user_id)
         )
     AND EXISTS (
           SELECT 1
             FROM public.organization_members m2
            WHERE m2.organization_id = p_org_id
              AND m2.user_id = (SELECT auth.uid())
         )
     AND COALESCE((public.check_feature_access(p_org_id, 'transaction_checklists') ->> 'allowed')::boolean, false);
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public.can_edit_checklist_templates(uuid)'::regprocedure) LIKE '%m2.organization_id = p_org_id%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('role and membership tested separately') AS mutation;
